String runtimeLog = "";
void rlog(String m){ runtimeLog += m + "\n"; if(runtimeLog.length()>8000) runtimeLog = runtimeLog.substring(4000); Serial.println(m); }

// ===== СКАН =====
void doScan(){
  networks.clear();
  int n = WiFi.scanNetworks(false,true);
  for(int i=0;i<n;i++){
    WifiInfo w;
    w.ssid = WiFi.SSID(i); if(w.ssid=="") w.ssid="<hidden>";
    w.bssid = WiFi.BSSIDstr(i);
    w.rssi = WiFi.RSSI(i);
    w.channel = WiFi.channel(i);
    w.auth = WiFi.encryptionType(i);
    w.authStr = authToString(w.auth);
    w.vendor = vendorByOui(w.bssid);
    networks.push_back(w);
  }
  WiFi.scanDelete();
  rlog("[scan] найдено: "+String(n));
}

