// ===== PROBE SNIFF =====
void probeSniffer(void* buf, wifi_promiscuous_pkt_type_t type){
  if(type!=WIFI_PKT_MGMT) return;
  wifi_promiscuous_pkt_t* p=(wifi_promiscuous_pkt_t*)buf;
  uint8_t* f=p->payload;
  if(f[0]!=0x40) return; // probe request
  char mac[18];
  sprintf(mac,"%02X:%02X:%02X:%02X:%02X:%02X",f[10],f[11],f[12],f[13],f[14],f[15]);
  int len=f[25];
  String ssid="";
  if(len>0 && len<33){
    char s[33]={0};
    memcpy(s,&f[26],len);
    ssid=String(s);
  }
  if(ssid.length()>0){
    bool dup=false;
    for(auto &pr:probes) if(pr.mac==String(mac) && pr.ssid==ssid) dup=true;
    if(!dup){
      probes.push_back({String(mac),ssid,p->rx_ctrl.rssi});
      rlog("[probe] "+String(mac)+" -> "+ssid);
    }
  }
}

void startSniff(){
  wifi_promiscuous_filter_t filt={.filter_mask=WIFI_PROMIS_FILTER_MASK_MGMT};
  esp_wifi_set_promiscuous_filter(&filt);
  esp_wifi_set_promiscuous_rx_cb(&probeSniffer);
  esp_wifi_set_promiscuous(true);
}
void stopSniff(){ esp_wifi_set_promiscuous(false); }

String buildProbesHtml(){
